"""Exact ordinal control: exchange words across lines on the same public page."""
import hashlib,json,random,sys
from collections import Counter,defaultdict
from pathlib import Path
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/'edge-position'))
import analyze as previous
from vs import corpus,dsl,generators,ivtff
FACT=previous.FACT
PLAN={
 'question':'Does edge association survive exact ordinal and length matching across lines on the same page?',
 'metric':'Unchanged edge_length_cmi in certain literal adjacent P tokens; no promotion across uncertain or empty words.',
 'primary_null':'Permute within (page, exact EVA-basic length, original line token count n, exact original word index k).',
 'paired_baseline':'Permute within (page, exact EVA-basic length, original line token count n, coarse initial/medial/final/singleton role).',
 'tradeoff':'Both new nulls allow exchanges between lines and do NOT preserve individual line inventories. They preserve each page inventory and positional length sequence. The exact-ordinal null is not a nested strengthening of the previous within-line null.',
 'impossible_null':'Within (original line, exact length, exact ordinal k), every cell is a singleton: no permutation is possible. Report as undefined, never as a successful test.',
 'sample':'The same34 public practice evaluation pages in ZL and IT; not new independent pages.',
 'replicates':199,'seed':408,'alpha':.01,
 'decision':'Require primary p<=.01 in both editions, >=30 potentially movable pairs and a nonconstant null. If not enough movement report undefined, never relax cells after results.',
 'controls':[{'generator':'G-line-chain','seed':4,'order':4},{'generator':'unigram','seed':221}],
 'limits':'Exact transcription ordinal and token-count width, not physical x coordinates, glyph spacing, ink width or identical row composition. One fixed seed per generator.',
 'fact_sha256':hashlib.sha256(FACT.read_bytes()).hexdigest()}

def groups(ts,mode):
    out=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']!='P' or ivtff.uncertain(t['w']) or not dsl.SEG(t['w']):continue
        if mode=='impossible':key=(t['line'],len(dsl.SEG(t['w'])),t['k'])
        else:key=(t['page'],len(dsl.SEG(t['w'])),t['n'],t['k'] if mode=='ordinal' else previous.role(t))
        out[key].append(i)
    return list(out.values())

def invariants(ts,sh,mode):
    for a,b in zip(ts,sh):
        assert {k:v for k,v in a.items() if k!='w'}=={k:v for k,v in b.items() if k!='w'}
        assert len(dsl.SEG(a['w']))==len(dsl.SEG(b['w']))
        if a['unit']!='P' or ivtff.uncertain(a['w']) or not dsl.SEG(a['w']):assert a['w']==b['w']
    for g in groups(ts,mode):assert Counter(ts[i]['w'] for i in g)==Counter(sh[i]['w'] for i in g)
    assert Counter((t['page'],t['w']) for t in ts)==Counter((t['page'],t['w']) for t in sh)

def movement(ts,gs,pairs):
    mutable={i for g in gs if len({ts[j]['w'] for j in g})>1 for i in g}
    spots={(ts[i]['line'],ts[i]['k']) for i in mutable}
    return sum((a['line'],a['k']) in spots or (b['line'],b['k']) in spots for a,b in pairs)

def run(pages):
    ts=dsl.tokens(pages);selected=dsl.select(ts,{'unit':['P'],'certain':True})
    statistic={'edge_length_cmi':True};observed=dsl.statistic(statistic,selected,ts)
    pairs=dsl._edge_length_pairs(selected)
    impossible=groups(ts,'impossible');assert all(len(g)==1 for g in impossible)
    assert movement(ts,impossible,pairs)==0
    result={'pages':len(pages),'observed_bits':observed,'pairs':len(pairs),
            'within_line_exact_ordinal':{'movable_pairs':0,'status':'undefined: every cell is a singleton'},'nulls':{}}
    for mode in ('role','ordinal'):
        gs=groups(ts,mode);movable=movement(ts,gs,pairs)
        if movable<30:
            result['nulls'][mode]={'status':'undefined: fewer than30 movable pairs','movable_pairs':movable};continue
        rng=random.Random(408);values=[]
        for i in range(199):
            sh=previous.permute(ts,gs,rng)
            if i==0:invariants(ts,sh,mode)
            values.append(dsl.statistic(statistic,dsl.select(sh,{'unit':['P'],'certain':True}),sh))
        nonconstant=any(abs(v-observed)>1e-12 for v in values)
        p=(1+sum(v>=observed for v in values))/200
        result['nulls'][mode]={'status':'defined' if nonconstant else 'undefined: constant null',
            'movable_pairs':movable,'movable_pair_share':movable/len(pairs),'p':p if nonconstant else None,
            'null_mean':sum(values)/len(values),'null_min':min(values),'null_max':max(values),
            'excess':observed-sum(values)/len(values),'passes':nonconstant and p<=.01,
            'first_shuffle_invariants_passed':True,'permutation_values':values}
    return result

def selfcheck():
    from vs.ivtff import Page,Line
    pages=[]
    for pid in ('a','b'):
        p=Page(pid,len(pages),{'I':'H','L':'A','H':'1'})
        for i,ws in enumerate([['aa','ch','a','?','rr'],['rr','a','ch','?','aa'],['a','rr'],['aa','rr','oo'],['','aa','rr','oo',''],['a']]):
            p.lines.append(Line(str(i),pid,i,'P','0',ws,False,False))
        pages.append(p)
    ts=dsl.tokens(pages);gs=groups(ts,'ordinal');sh=previous.permute(ts,gs,random.Random(408));invariants(ts,sh,'ordinal')
    assert any(a['w']!=b['w'] for a,b in zip(ts,sh))
    # Tokens of different widths or pages never share a cell even at the same k/length.
    for g in gs:
        assert len({(ts[i]['page'],ts[i]['n'],ts[i]['k'],len(dsl.SEG(ts[i]['w']))) for i in g})==1
    deg=groups(ts,'impossible');assert all(len(g)==1 for g in deg)
    assert previous.permute(ts,deg,random.Random(408))==ts
    return 'Fixture passes: page, width, ordinal, EVA glyph length, metadata and barriers; real cross-line exchange; impossible within-line control is inert.'

if __name__=='__main__':
    if '--plan' in sys.argv:
        ROOT.mkdir(exist_ok=True);(ROOT/'plan.json').write_text(json.dumps(PLAN,indent=2)+'\n',encoding='utf-8');print('Plan frozen');sys.exit()
    assert json.loads((ROOT/'plan.json').read_text())==PLAN
    report={'plan':PLAN,'selfcheck':selfcheck(),'results':{}}
    for ed in ('zl','it'):
        train,ev=corpus.split_pages('practice',ed)
        pool=[w for p in train for ln in p.lines for w in ln.words if w and not ivtff.uncertain(w)]
        rng=random.Random(221)
        samples={'manuscript':ev,'G-line-chain':generators.g_line_chain(train,ev,seed=4,order=4),
                 'unigram':generators._shape_like(ev,lambda p,ln,i:rng.choice(pool))}
        report['results'][ed]={}
        for name,pages in samples.items():
            report['results'][ed][name]=run(pages)
            print(ed,name,{k:{a:b for a,b in v.items() if a!='permutation_values'} for k,v in report['results'][ed][name]['nulls'].items()},flush=True)
            (ROOT/'results.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    assert hashlib.sha256(FACT.read_bytes()).hexdigest()==PLAN['fact_sha256']
    report['fact_unchanged']=True
    (ROOT/'results.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')

